mapper.update:
                UPDATE SMT_APPROVE_LIST SAL
				SET SAL.APPROVE_STATE = #{query.approveState}
				WHERE
				    SAL.APPROVE_TYPE = #{query.approveType}
				AND SAL.APPROVE_BADGE = #{query.approveBadge}
				AND SAL.BUSINESS_ID = #{query.businessId}

mapper.select:
SELECT SAL.ID, SAL.BUSINESS_ID, SAL.APPROVE_NAME, SAL.APPROVE_TYPE, SAL.APPROVE_STATE, SAL.CREATE_TIME, SAL.APPROVE_BADGE, SAL.SORT, SAL.NODE_ID, SAL.REMARK FROM SMT_APPROVE_LIST SAL LEFT JOIN SMT_ARTICLES_RELEASE SAR ON SAL.BUSINESS_ID = SAR.ID WHERE SAL.APPROVE_BADGE = #{approveBadge} AND SAL.APPROVE_TYPE = #{query.recordType}
AND SAL.APPROVE_STATE IN
#{state}
AND SAR.CARRIER LIKE CONCAT('%', CONCAT(#{query.name}, '%'))
AND SAR.BADGE = #{query.badge}
AND SAR.CREATE_TIME > to_date(#{query.startTime}, 'yyyy-mm-dd hh24:mi:ss')
AND SAR.CREATE_TIME < to_date(#{query.endTime}, 'yyyy-mm-dd hh24:mi:ss')
ORDER BY SAL.CREATE_TIME DESC
